ALTER TABLE readings
    ADD COLUMN cover_key VARCHAR(120);

UPDATE readings
SET cover_key = CASE id
    WHEN '30000000-0000-0000-0000-000000000009' THEN 'the-camera-on-platform-three'
    WHEN '30000000-0000-0000-0000-000000000017' THEN 'the-library-book-with-no-author'
    WHEN '30000000-0000-0000-0000-000000000027' THEN 'the-station-outside-the-map'
    WHEN '30000000-0000-0000-0000-000000000029' THEN 'the-coral-ledger'
    WHEN '30000000-0000-0000-0000-000000000035' THEN 'the-city-beneath-the-reservoir'
    WHEN '30000000-0000-0000-0000-000000000036' THEN 'the-memory-orchard'
    WHEN '30000000-0000-0000-0000-000000000044' THEN 'the-grammar-of-tides'
    WHEN '30000000-0000-0000-0000-000000000050' THEN 'the-unreliable-future-perfect'
END
WHERE id IN (
    '30000000-0000-0000-0000-000000000009',
    '30000000-0000-0000-0000-000000000017',
    '30000000-0000-0000-0000-000000000027',
    '30000000-0000-0000-0000-000000000029',
    '30000000-0000-0000-0000-000000000035',
    '30000000-0000-0000-0000-000000000036',
    '30000000-0000-0000-0000-000000000044',
    '30000000-0000-0000-0000-000000000050'
